import math

def test_known_pair():
    got = solution.preference_loss([(2.0, 1.0)])
    assert abs(got - 0.3132616875182228) < 1e-9

def test_tie_costs_log_two():
    got = solution.preference_loss([(1.0, 1.0)])
    assert abs(got - math.log(2.0)) < 1e-9

def test_mean_over_pairs():
    got = solution.preference_loss([(2.0, 1.0), (1.2, 1.0)])
    assert abs(got - 0.4557002784499073) < 1e-9

def test_only_the_difference_matters():
    a = solution.preference_loss([(5.0, 4.0)])
    b = solution.preference_loss([(2.0, 1.0)])
    assert abs(a - b) < 1e-12

def test_empty_raises():
